function drawTree(x, y, trunkColor, leafColor) {
    // Trunk
    ctx.fillStyle = trunkColor;
    ctx.fillRect(x, y, 10, 30);

    // Leaves
    ctx.fillStyle = leafColor;
    ctx.beginPath();
    ctx.moveTo(x - 15, y);
    ctx.lineTo(x + 15, y);
    ctx.lineTo(x, y - 25);
    ctx.closePath();
    ctx.fill();
}

