// Draw marbles (spheres with shading)
function drawMarble(x, y, size, color) {
    // Marble body
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();

    // Marble highlight
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(x - size/4, y - size/4, size/4, 0, Math.PI * 2);
    ctx.fill();

    // Marble shadow
    ctx.fillStyle = '#cccccc';
    ctx.beginPath();
    ctx.arc(x + size/4, y + size/4, size/4, 0, Math.PI * 2);
    ctx.fill();
}

