        // Alternate colors for checker pattern
        if ((row + col) % 2 === 0) {
            drawMarble(offsetX + col * squareSize, offsetY + row * squareSize, squareSize - 3, '#000000');
        } else {
            drawMarble(offsetX + col * squareSize, offsetY + row * squareSize, squareSize - 3, '#FFFFFF');
        }
    }
}

