// Draw circles with gradient fill
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 30;

  // Create gradient
  const gradient = ctx.createRadialGradient(
    centerX, centerY,
    radius - 20,
    centerX, centerY,
    radius + 20
  );

  gradient.addColorStop(0, colors[i]);
  gradient.addColorStop(1, '#ffffff');

  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fillStyle = gradient;
  ctx.fill();
}

// Draw radial lines
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 1;
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const startX = centerX + Math.cos(angle) * (maxRadius - 20);
  const startY = centerY + Math.sin(angle) * (maxRadius - 20);
  const endX = centerX + Math.cos(angle) * (maxRadius + 20);
  const endY = centerY + Math.sin(angle) * (maxRadius + 20);
  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();
}

