// Draw diagonal bands
ctx.strokeStyle = '#2d2d44';
ctx.lineWidth = 2;
for (let i = 0; i < 4; i++) {
  const angle1 = (i / 4) * Math.PI * 2;
  const angle2 = (i / 4 + 0.5) * Math.PI * 2;

  const startX1 = centerX + Math.cos(angle1) * (maxRadius - 10);
  const startY1 = centerY + Math.sin(angle1) * (maxRadius - 10);
  const endX1 = centerX + Math.cos(angle1) * (maxRadius + 10);
  const endY1 = centerY + Math.sin(angle1) * (maxRadius + 10);

  const startX2 = centerX + Math.cos(angle2) * (maxRadius - 10);
  const startY2 = centerY + Math.sin(angle2) * (maxRadius - 10);
  const endX2 = centerX + Math.cos(angle2) * (maxRadius + 10);
  const endY2 = centerY + Math.sin(angle2) * (maxRadius + 10);

  ctx.beginPath();
  ctx.moveTo(startX1, startY1);
  ctx.lineTo(endX1, endY1);
  ctx.moveTo(startX2, startY2);
  ctx.lineTo(endX2, endY2);
  ctx.stroke();
}

