// Draw spiral
function drawSpiral(x, y, r, depth) {
    if (depth > 0) {
        // Draw arc
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.strokeStyle = C5;
        ctx.lineWidth = 2;
        ctx.stroke();

        // Recursive calls for four arms
        drawSpiral(x + r, y, r * 0.8, depth - 1);
        drawSpiral(x - r, y, r * 0.8, depth - 1);
        drawSpiral(x, y + r, r * 0.8, depth - 1);
        drawSpiral(x, y - r, r * 0.8, depth - 1);
    }
}

