// Shell spiral
ctx.fillStyle = '#8B4513';
ctx.beginPath();
let r = 10;
for (let i = 0; i < 20; i++) {
    const angle = i * 0.3;
    const x = 200 + Math.cos(angle) * r;
    const y = 250 + Math.sin(angle) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
    r += 3;
}
ctx.closePath();
ctx.fill();

// Shell details
ctx.fillStyle = '#A0522D';
for (let i = 0; i < 15; i++) {
    const angle = i * 0.3;
    const x = 200 + Math.cos(angle) * (r + 2);
    const y = 250 + Math.sin(angle) * (r + 2);
    ctx.beginPath();
    ctx.arc(x, y, 2, 0, Math.PI * 2);
    ctx.fill();
}

