// Snail legs
ctx.strokeStyle = '#000';
ctx.lineWidth = 3;
for (let i = 0; i < 4; i++) {
    const angle = (i * Math.PI / 2) - (Math.PI / 8);
    const x1 = 200 + Math.cos(angle) * 15;
    const y1 = 250 + Math.sin(angle) * 15;
    const x2 = 200 + Math.cos(angle) * 25;
    const y2 = 250 + Math.sin(angle) * 25;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
}

